module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

reg [5:0] cnt_50;
reg [3:0] cnt_10;
reg [6:0] cnt_1;

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        CLK_50 <= 0;
        CLK_10 <= 0;
        CLK_1 <= 0;
        cnt_50 <= 0;
        cnt_10 <= 0;
        cnt_1 <= 0;
    end else begin

        CLK_50 <= ~CLK_50;

        if (cnt_10 == 4) begin
            CLK_10 <= ~CLK_10;
            cnt_10 <= 0;
        end else begin
            cnt_10 <= cnt_10 + 1;
        end

        if (cnt_1 == 49) begin
            CLK_1 <= ~CLK_1;
            cnt_1 <= 0;
        end else begin
            cnt_1 <= cnt_1 + 1;
        end
    end
end

endmodule
